·
switch (ch) {
case 'Y':
/* ch == 'Y' */
/* do something */
break;
case 'N':
/* ch == 'N' */
/* do something else */
break;
default:
/* otherwise */
/* do a third thing */
break;
}
switch (ch) {
case 'Y':
case 'y':
/* do something if ch == 'Y' or ch == 'y' */
break;
}
